<template><div class="admin-team-page"><RouterLink to="/admin-dashboard">← 返回管理员工作台</RouterLink><div class="admin-team-heading"><div><h1>球队报名审核</h1><p class="help">线上报名先检查必填资料和赛事配置的报名限制，再进行人工审核。自动审核失败的申请保留在列表中。</p></div><RouterLink to="/admin-seasons">设置报名窗口 →</RouterLink></div>
  <div class="admin-team-tabs"><button :aria-pressed="tab==='applications'" @click="switchTab('applications')">整队报名</button><button :aria-pressed="tab==='roles'" @click="switchTab('roles')">角色变更</button></div><label class="season-select">球队审核赛季<select :value="seasonId" :disabled="busy" @change="changeSeason"><option value="">当前启用赛季</option><option v-for="s in seasons" :key="s.id" :value="String(s.id)">{{ s.season_name }}</option></select></label>
  <AdminTeamRoleReview v-if="tab==='roles'" :season-id="seasonId"/>
  <template v-else><p v-if="error" class="notice error" role="alert">{{ error }}</p><p v-if="success" class="notice success" role="status">{{ success }}</p><form class="admin-team-filters" @submit.prevent="search"><label>报名赛事<select v-model="league"><option value="">全部赛事</option><CompetitionOptions :season-id="seasonId" /></select></label><label>球队申请状态<select v-model="status"><option value="">全部状态</option><option v-for="(label,value) in labels" :key="value" :value="value">{{ label }}</option></select></label><label>查询队名<input v-model="q" maxlength="100" placeholder="队伍名称"></label><button :disabled="busy||loading">查询球队报名</button></form>
    <div class="team-table-wrap"><table><thead><tr><th>队名</th><th>赛事</th><th>名单人数</th><th>状态</th><th>提交时间</th><th>操作</th></tr></thead><tbody><tr v-for="v in items" :key="v.id"><td>{{ v.team_name }}<br><small>{{ v.kind==='roster_change'?'名单变更':'首次报名' }}{{ v.source_type==='admin_import'?' · Excel导入':'' }}</small></td><td>{{ v.league_type }}</td><td>{{ v.member_count }}</td><td>{{ labels[v.status] }}<small v-if="v.auto_review?.manual_requested && v.status==='pending'"> · 申请人工审核</small><ul v-if="v.status==='auto_failed'"><li v-for="failure in v.auto_review?.failures||[]" :key="failure.rule">{{ failure.message }}</li></ul></td><td>{{ time(v.submitted_at) }}</td><td><button :disabled="busy" @click="open(v.id)">查看球队申请</button></td></tr><tr v-if="!items.length"><td colspan="6">{{ loading?'正在读取…':'暂无符合条件的球队报名' }}</td></tr></tbody></table></div><div class="team-pagination"><span>共 {{ pagination.total }} 份 · 第 {{ page }} 页</span><button :disabled="busy||loading||page<=1" @click="page--;load()">上一页</button><button :disabled="busy||loading||page>=pagination.total_pages" @click="page++;load()">下一页</button></div>
    <section v-if="detail" class="team-review-detail"><div class="admin-team-heading"><div><span class="help">{{ detail.application.season_name }} · {{ detail.application.league_type }}</span><h2>{{ detail.application.team_name }} · {{ detail.application.kind==='roster_change'?'名单变更':'首次报名' }}</h2></div><div class="admin-team-actions"><button :disabled="busy" @click="open(detail.application.id)">刷新球队申请</button><button :disabled="busy" @click="close">关闭详情</button></div></div><p>负责人：{{ detail.manager.name }} · {{ detail.manager.student_id }}　状态：{{ labels[detail.application.status] }}</p><p>球衣（上衣／裤子／袜子）：{{ detail.application.shirt_color||'/' }} / {{ detail.application.shorts_color||'/' }} / {{ detail.application.socks_color||'/' }}</p><p v-if="detail.window.rules_text" class="notice">赛事规则：{{ detail.window.rules_text }}</p><p v-if="detail.application.return_reason" class="notice">上次退回理由：{{ detail.application.return_reason }}</p><p v-if="detail.application.revoke_reason" class="notice">上次撤销通过原因：{{ detail.application.revoke_reason }}</p><div class="admin-team-counts"><strong>总人数 {{ detail.summary.total }}</strong><strong>外援 {{ detail.summary.foreign }}</strong><strong v-if="detail.window.limits.enable_sports_training">运训 {{ detail.summary.sports_training }}</strong><strong v-if="detail.window.limits.enable_football_specialty">足球特长生 {{ detail.summary.football_specialty }}</strong><strong>守门员 {{ detail.summary.goalkeepers }}</strong></div><p class="help">参队情况覆盖本赛季全部比赛类型，包含同类赛事和其它类型赛事，逐队注明所属比赛类型。球队数和明细均按当前有效正式名单统计，不含本队、待审申请及已退出名单；参队数量不设自动上限。</p>
      <TeamAutomaticReview :limits="detail.window.limits" :result="detail.auto_review" :current="detail.current_auto_review"/>
      <p v-if="detail.application.source_type==='admin_import'" class="help">管理员特殊导入保留例外，不执行线上报名自动限制。</p>
      <article v-for="m in detail.members" :key="m.id" class="review-member"><div class="admin-team-heading"><div><h3>{{ m.jersey_number??'未分配号码' }}号 · {{ m.name }}</h3><p>{{ m.student_id }} · {{ m.college }} · {{ m.gender==='male'?'男':m.gender==='female'?'女':'未填写性别' }}</p><p class="help">{{ qualifications[m.qualification_status]||'尚未注册学籍' }}{{ m.account_active?'':' · 账号停用' }} · 本赛季其它已通过球队数（全部赛事）：<strong>{{ m.approved_teams?.length || 0 }}</strong></p><p class="help">{{ m.is_captain?'场上队长 · ':'' }}{{ m.is_goalkeeper?'守门员 · ':'' }}{{ m.is_foreign?'外援 · ':'' }}{{ m.is_sports_training?'运训 ':'' }}{{ m.is_football_specialty?'足球特长生':'' }}</p><p v-if="detail.application.source_type!=='admin_import'" class="help">自动审核计入学院（账号最新资料）：{{ m.auto_review_college || '未填写' }}<span v-if="m.account_college && m.account_college !== m.auto_review_college">（账号填写：{{ m.account_college }}）</span></p><p class="help">学籍审核当时学院（留档）：{{ m.reviewed_college || '未记录' }}</p><p v-if="!m.approved_teams?.length">并无参加其它队伍</p><ul v-else class="approved-teams"><li v-for="team in m.approved_teams" :key="team.id">已参加 {{ team.team_name }}（{{ team.league_type }}）</li></ul></div><button :disabled="busy||!m.registration_id" @click="showMaterial(m.registration_id)">{{ m.name }}学籍详情</button></div><p class="submission-profile">本次名单资料快照：{{ m.profile_snapshot.name }} / {{ m.profile_snapshot.student_id }} / {{ m.profile_snapshot.college }}</p>
        <div v-if="detail.permissions.can_return && !detail.application.registration_revoked" class="member-return-controls"><label class="admin-team-check"><input v-model="replaceable" type="checkbox" :value="m.id" :aria-label="'允许替换'+m.name" :disabled="busy">退回后允许截止外替换此球员</label><label>{{ m.name }}的退回说明<textarea v-model="comments[m.id]" maxlength="500" rows="2" :disabled="busy" placeholder="可选：具体不符合的要求"></textarea></label></div>
      </article>
      <section v-if="material" class="academic-review"><div class="admin-team-heading"><h3>{{ material.account.name }} · 学籍审核材料</h3><button @click="material=null">关闭学籍材料</button></div><p class="help">学籍提交时：{{ material.registration.profile_snapshot.name }} / {{ material.registration.profile_snapshot.student_id }} / {{ material.registration.profile_snapshot.college }}</p><PlayerAcademicImage v-if="material.files[0]?.available" :registration-id="material.registration.id" :file-id="material.files[0].id"/><p v-else>材料已清理或不可用。</p></section>
      <section v-if="detail.correction.differences.length" class="notice"><h3>与原名单或上次退回版本的差异</h3><ul><li v-for="(line,i) in detail.correction.differences" :key="i">{{ line }}</li></ul></section>
      <div v-if="detail.permissions.can_undo_return || detail.permissions.can_undo_revoke" class="team-review-actions"><p class="help">球队尚未修改或重新提交，可恢复到误操作前的状态。</p><button v-if="detail.permissions.can_undo_return" :disabled="busy" @click="review('undo-return')">撤销退回球队补正</button><button v-if="detail.permissions.can_undo_revoke" :disabled="busy" @click="review('undo-revoke')">撤销撤销报名通过（恢复通过）</button></div><div v-if="detail.permissions.can_revoke" v-draft="{ value: {reason}, resetKey: detail.application.id }" class="team-review-actions"><label>撤销通过原因（必填，向球队展示）<textarea v-model="reason" maxlength="500" rows="3" :disabled="busy" placeholder="请说明撤销报名通过的原因"></textarea></label><p class="help">撤销后沿用当前负责人、队长和最新正式名单，球队可在报名时间内修改原申请并重新提交。已有赛程和历史记录保留；重新审核通过前不能安排新赛程。</p><button :disabled="busy || !reason.trim()" @click="review('revoke')">撤销报名通过</button></div><div v-else-if="detail.permissions.can_return" v-draft="{ value: {reason, comments, replaceable}, resetKey: detail?.application.id }" class="team-review-actions"><label>整队审核说明／退回理由／人工通过原因<textarea v-model="reason" maxlength="500" rows="3" :disabled="busy" placeholder="退回或人工通过自动失败时必填，可说明处理依据"></textarea></label><p v-if="detail.application.registration_revoked" class="help">此队报名通过已撤销，退回后仍须在报名时间内修改和重新提交。</p><p v-else class="help">退回后截止外只能替换上方勾选的球员，其余人员锁定；号码、角色、标记和球队资料可按理由补正。通过时将再次核对全部球员资格。</p><div class="admin-team-actions"><button v-if="detail.permissions.can_review" class="primary" :disabled="busy" @click="review('approve')">{{ detail.current_auto_review && !detail.current_auto_review.passed ? '重新自动检查（失败则记录原因）' : detail.application.kind==='roster_change'?'通过名单变更（立即生效）':'通过整队报名' }}</button><button v-if="detail.permissions.can_override" class="primary" :disabled="busy" @click="review('override-approve')">人工通过自动审核失败</button><button :disabled="busy" @click="review('return')">退回球队补正</button></div></div><p v-else class="help">当前申请只读；当前启用赛事的待审申请可以批准或退回；自动失败申请可以填写原因后人工通过或退回补正。</p>
      <details v-if="detail.events.length" class="admin-team-history"><summary>整队操作记录（最近100条）</summary><ol><li v-for="e in detail.events" :key="e.id"><strong>{{ operations[e.operation] }}</strong> · {{ time(e.created_at) }} · {{ e.actor_admin_id?'管理员 #'+e.actor_admin_id:'球员 #'+e.actor_player_id }}<p v-if="e.reason">{{ e.reason }}</p><p v-for="(line,i) in e.changes||[]" :key="i">{{ line }}</p><details><summary>查看当时名单</summary><ul><li v-for="m in e.after_snapshot.members" :key="m.id">{{ m.jersey_number??'未分配' }}号 · {{ m.profile_snapshot.name }} / {{ m.profile_snapshot.student_id }} / {{ m.profile_snapshot.college }}{{ m.is_captain?' · 队长':'' }}{{ m.is_foreign?' · 外援':'' }}{{ m.is_sports_training?' · 运训':'' }}{{ m.is_football_specialty?' · 足球特长生':'' }}</li></ul></details></li></ol></details>
    </section>
  </template>
</div></template>
<script setup>
import TeamAutomaticReview from '../../../shared-ui/TeamAutomaticReview.vue'
import CompetitionOptions from '../components/CompetitionOptions.vue'
import { confirmDraftLeave } from '../../../shared-ui/interaction.js'
import { ref,onMounted } from 'vue'
import api from '../api/http'
import PlayerAcademicImage from '../components/PlayerAcademicImage.vue'
import AdminTeamRoleReview from '../components/AdminTeamRoleReview.vue'
import '../teamReview.css'
const seasons=ref([]),seasonId=ref(''),tab=ref('applications'),league=ref(''),status=ref(''),q=ref(''),page=ref(1),items=ref([]),pagination=ref({total:0,total_pages:0}),detail=ref(null),material=ref(null),replaceable=ref([]),comments=ref({}),reason=ref(''),busy=ref(false),loading=ref(false),error=ref(''),success=ref('');let sequence=0,detailSequence=0,materialSequence=0
const labels={draft:'草稿',pending:'待审核',returned:'已退回',withdrawn:'已撤回',approved:'已通过',revoked:'已撤销通过',auto_failed:'自动审核失败'},operations={created:'创建草稿',saved:'保存草稿',submitted:'提交整队审核',withdrawn:'撤回报名',returned:'管理员退回',approved:'审核通过',revoked:'管理员撤销通过',admin_updated:'管理员修改球队',return_undone:'撤销退回',revoke_undone:'恢复报名通过',auto_failed:'自动审核失败',identity_linked:'关联导入身份'},qualifications={approved:'学籍已通过',pending:'学籍待审核',returned:'学籍已退回',withdrawn:'学籍已撤回',revoked:'资格已撤销'}
const time=v=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—',fail=e=>error.value=e.response?.data?.message||'操作失败，请重试'
function assign(d){detail.value=d;replaceable.value=[];comments.value={};reason.value='';material.value=null;materialSequence++}
async function load(){const n=++sequence;loading.value=true;try{const r=await api.get('/player-admin/team-applications',{params:{season_id:seasonId.value||undefined,league_type:league.value,status:status.value,q:q.value,page:page.value}});if(n===sequence){items.value=r.data.items;pagination.value=r.data.pagination}}catch(e){if(n===sequence)fail(e)}finally{if(n===sequence)loading.value=false}}
function switchTab(value){if(confirmDraftLeave())tab.value=value}
function changeSeason(event){if(!confirmDraftLeave()){event.target.value=seasonId.value;return}seasonId.value=event.target.value;search()}
function close(){if(!confirmDraftLeave(document.querySelector('.team-review-actions')))return;detailSequence++;materialSequence++;detail.value=null;material.value=null}
function search(){if(!confirmDraftLeave(document.querySelector('.team-review-actions')))return;page.value=1;close();error.value='';success.value='';load()}
async function open(id){if(!confirmDraftLeave(document.querySelector('.team-review-actions')))return;const n=++detailSequence;close();const current=detailSequence;error.value='';success.value='';try{const r=await api.get('/player-admin/team-applications/'+id);if(current===detailSequence)assign(r.data)}catch(e){if(current===detailSequence)fail(e)}}
async function showMaterial(id){const n=++materialSequence;material.value=null;try{const r=await api.get('/player-admin/season-registrations/'+id);if(n===materialSequence)material.value=r.data}catch(e){if(n===materialSequence)fail(e)}}
async function review(action){if(action.startsWith('undo-')&&!window.confirm('确认撤销这次误操作并恢复原状态？球队已有后续修改时将禁止恢复。'))return;if(action==='revoke'&&!window.confirm('确认撤销这支球队的报名通过？已有赛程和历史记录保留，球队须在报名时间内重新提交并通过审核。'))return;busy.value=true;error.value='';success.value='';const body={reason:reason.value,review_token:detail.value.review_token};if(action==='return'){body.replaceable_member_ids=replaceable.value;body.member_comments=comments.value}try{const r=await api.post(`/player-admin/team-applications/${detail.value.application.id}/${action}`,body,{headers:{'If-Match':String(detail.value.application.revision)}});assign(r.data);if(r.data.application.status==='auto_failed'&&!action.startsWith('undo-')){error.value='按最新规则自动审核失败，原因已保存。可退回补正，或填写原因后人工通过。';success.value=''}else success.value=action==='undo-return'?'已撤销退回，申请已恢复原审核状态。':action==='undo-revoke'?'已恢复报名通过，球队及原正式名单继续有效。':action==='revoke'?'已撤销报名通过，原因已通知球队；报名时间内可修改原申请并重新提交。':action==='override-approve'?'已人工通过，自动失败原因和人工通过依据已保留。':action==='approve'?'球队报名已通过，已进入正式球队库。':'球队报名已退回，补正范围已经保存。';await load()}catch(e){fail(e)}finally{busy.value=false}}
onMounted(async()=>{try{seasons.value=(await api.get('/season')).data;await load()}catch(e){fail(e)}})
</script>
